<?php
$stats=one("SELECT COUNT(*) total,SUM(status IN ('confirmed','production')) production,SUM(due_date<CURDATE() AND status NOT IN ('shipped','cancelled')) overdue,SUM(status='ready') ready FROM orders");
$followups=rows("SELECT n.*,o.code FROM notes n JOIN orders o ON o.id=n.order_id WHERE n.done=0 AND n.followup_date IS NOT NULL AND n.followup_date<=DATE_ADD(CURDATE(),INTERVAL 7 DAY) AND o.status NOT IN ('shipped','cancelled') ORDER BY n.followup_date LIMIT 15");
$work=rows("SELECT s.*,i.name item_name,i.order_id,o.code FROM item_steps s JOIN items i ON i.id=s.item_id JOIN orders o ON o.id=i.order_id WHERE s.status<>'done' AND o.status NOT IN ('shipped','cancelled') ORDER BY (s.status='blocked') DESC,(s.due_date IS NULL),s.due_date LIMIT 15");
?><div class="toolbar"><p class="muted">Your next decisions, deadlines and production tasks.</p><a class="button" href="index.php?page=order">+ New order</a></div>
<div class="stats"><?php foreach(['total'=>'All orders','production'=>'In production / confirmed','overdue'=>'Overdue orders','ready'=>'Ready to ship'] as $k=>$label): ?><section class="card"><p><?=e($label)?></p><strong><?=e($stats[$k]??0)?></strong></section><?php endforeach ?></div>
<div class="columns"><section class="card"><h2>Production focus</h2><div class="table-wrap"><table><thead><tr><th>Item / order</th><th>Step</th><th>Status</th><th>Due</th></tr></thead><tbody><?php foreach($work as $w): ?><tr><td><a href="index.php?page=item&id=<?=$w['item_id']?>"><?=e($w['item_name'])?></a><small><?=e($w['code'])?></small></td><td><?=e($w['name'])?></td><td><?php badge($w['status']); ?></td><td><?=e($w['due_date']??'Unscheduled')?></td></tr><?php endforeach ?><?php if(!$work): ?><tr><td colspan="4">No open production steps. Add an item to get started.</td></tr><?php endif ?></tbody></table></div></section>
<section class="card"><h2>Follow-ups · next 7 days</h2><?php foreach($followups as $n): ?><article class="note"><a href="index.php?page=order&id=<?=$n['order_id']?>"><?=e($n['code'])?></a><p><?=nl2br(e($n['body']))?></p><small>Due <?=e($n['followup_date'])?></small></article><?php endforeach ?><?php if(!$followups): ?><p class="muted">No follow-ups due this week.</p><?php endif ?></section></div>
